CREATE TABLE schema_meta (key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE settings (section TEXT PRIMARY KEY, value TEXT NOT NULL CHECK (json_valid(value)), updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE conversations (id TEXT PRIMARY KEY, title TEXT, started_at INTEGER NOT NULL, ended_at INTEGER, digest TEXT, digest_upto_seq INTEGER NOT NULL DEFAULT 0) STRICT;
CREATE TABLE utterances (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations ON DELETE CASCADE, started_at INTEGER NOT NULL, duration_ms INTEGER NOT NULL, stt_model TEXT, stt_ms INTEGER, text TEXT, disposition TEXT NOT NULL CHECK (disposition IN ('intake','prefiltered','control','answer_bypass','self_echo','stt_failed')), filter_reason TEXT, audio_path TEXT) STRICT;
CREATE TABLE messages (id TEXT PRIMARY KEY, conversation_id TEXT NOT NULL REFERENCES conversations ON DELETE CASCADE, seq INTEGER NOT NULL, role TEXT NOT NULL CHECK (role IN ('user','bot')), source TEXT NOT NULL CHECK (source IN ('voice','typed','system')), kind TEXT NOT NULL CHECK (kind IN ('text','ask','confirm','result','answer','media','notice')), text TEXT NOT NULL, utterance_id TEXT REFERENCES utterances ON DELETE SET NULL, task_id TEXT, intent TEXT CHECK (intent IN ('new_task','amend','answer','question','cancel','chatter')), intent_p REAL, disposition TEXT CHECK (disposition IN ('enqueued','offered','ignored','forced','delivered')), verdict_id TEXT, attachments TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(attachments)), spoken INTEGER NOT NULL DEFAULT 0, at INTEGER NOT NULL, UNIQUE (conversation_id, seq)) STRICT;
CREATE VIRTUAL TABLE messages_fts USING fts5(text, content='messages', content_rowid='rowid');
CREATE TRIGGER messages_ai AFTER INSERT ON messages BEGIN INSERT INTO messages_fts(rowid, text) VALUES (new.rowid, new.text); END;
CREATE TRIGGER messages_ad AFTER DELETE ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, text) VALUES ('delete', old.rowid, old.text); END;
CREATE TRIGGER messages_au AFTER UPDATE ON messages BEGIN INSERT INTO messages_fts(messages_fts, rowid, text) VALUES ('delete', old.rowid, old.text); INSERT INTO messages_fts(rowid, text) VALUES (new.rowid, new.text); END;
CREATE TABLE tasks (id TEXT PRIMARY KEY, conversation_id TEXT REFERENCES conversations ON DELETE SET NULL, origin_message_id TEXT, parent_task_id TEXT REFERENCES tasks ON DELETE SET NULL, text TEXT NOT NULL, goal TEXT, source TEXT NOT NULL CHECK (source IN ('voice','typed','retry','pin','system')), route TEXT NOT NULL CHECK (route IN ('navigate','design','media','multi','question','routine')), routine_ref TEXT, lane TEXT NOT NULL CHECK (lane IN ('desktop','readonly','canvas')), status TEXT NOT NULL CHECK (status IN ('queued','running','needs_confirm','waiting_user','done','failed','cancelled')), paused_reason TEXT CHECK (paused_reason IN ('queue_paused','screen_locked','display_asleep','user_active','daily_cap','jev_outage','key_invalid','offline')), fail_code TEXT, error TEXT, summary TEXT, say TEXT, position REAL NOT NULL, persona TEXT, studio_id TEXT, target_app TEXT, start_url TEXT, pack_set TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(pack_set)), caps TEXT NOT NULL CHECK (json_valid(caps)), steps INTEGER NOT NULL DEFAULT 0, jev_calls INTEGER NOT NULL DEFAULT 0, sol_calls INTEGER NOT NULL DEFAULT 0, cost_usd REAL NOT NULL DEFAULT 0, cost_exact INTEGER NOT NULL DEFAULT 0, progress REAL NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, started_at INTEGER, finished_at INTEGER) STRICT;
CREATE INDEX tasks_queue ON tasks (status, lane, position);
CREATE TABLE task_amendments (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks ON DELETE CASCADE, message_id TEXT, text TEXT NOT NULL, at INTEGER NOT NULL, applied_after_seq INTEGER) STRICT;
CREATE TABLE trace_items (task_id TEXT NOT NULL REFERENCES tasks ON DELETE CASCADE, seq INTEGER NOT NULL, step INTEGER, kind TEXT NOT NULL CHECK (kind IN ('route','thought','action','steer','judgment','saw','said','asked','amended','gate','spend','pack','canvas','error')), at INTEGER NOT NULL, dur_ms INTEGER, enc INTEGER NOT NULL DEFAULT 0, body BLOB NOT NULL, PRIMARY KEY (task_id, seq)) STRICT, WITHOUT ROWID;
CREATE TABLE task_checkpoints (task_id TEXT PRIMARY KEY REFERENCES tasks ON DELETE CASCADE, state BLOB NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE jev_verdicts (id TEXT PRIMARY KEY, at INTEGER NOT NULL, caller TEXT NOT NULL CHECK (caller IN ('intake','route','routine_match','nav_step','gate','grounding','verify','micro_edit')), task_id TEXT REFERENCES tasks ON DELETE SET NULL, step INTEGER, message_id TEXT, model TEXT, rules_version TEXT, enc INTEGER NOT NULL DEFAULT 0, request BLOB, answers TEXT NOT NULL CHECK (json_valid(answers)), outcome TEXT NOT NULL CHECK (outcome IN ('ok','timeout','invalid','http_error')), latency_ms INTEGER NOT NULL, input_tokens INTEGER, output_tokens INTEGER, human_signal TEXT CHECK (human_signal IN ('approved','denied','force_enqueued','offer_accepted','cancelled_after','retried','undone','corrected')), human_signal_at INTEGER) STRICT;
CREATE INDEX jev_verdicts_task ON jev_verdicts (task_id, step);
CREATE TABLE confirms (id TEXT PRIMARY KEY, task_id TEXT NOT NULL REFERENCES tasks ON DELETE CASCADE, step INTEGER, verdict_id TEXT, raised_by TEXT NOT NULL CHECK (raised_by IN ('rule','head','spend','pack_policy','app_mode')), trigger TEXT NOT NULL, action_sentence TEXT NOT NULL, scope_kind TEXT CHECK (scope_kind IN ('app','origin')), scope TEXT, label TEXT, operation TEXT, risk TEXT CHECK (json_valid(risk)), est_usd REAL, status TEXT NOT NULL CHECK (status IN ('pending','approved','denied','timed_out','cancelled')), resolved_via TEXT CHECK (resolved_via IN ('ui','voice','timeout','kill')), remembered INTEGER NOT NULL DEFAULT 0, requested_at INTEGER NOT NULL, resolved_at INTEGER) STRICT;
CREATE TABLE remembered_allows (id TEXT PRIMARY KEY, scope_kind TEXT NOT NULL CHECK (scope_kind IN ('app','origin')), scope TEXT NOT NULL, label_norm TEXT NOT NULL, operation TEXT NOT NULL, from_confirm_id TEXT, created_at INTEGER NOT NULL, last_used_at INTEGER, uses INTEGER NOT NULL DEFAULT 0, UNIQUE (scope_kind, scope, label_norm, operation)) STRICT;
CREATE TABLE app_policies (bundle_id TEXT PRIMARY KEY, name TEXT, mode TEXT NOT NULL CHECK (mode IN ('allowed','confirm_all','denied')), ax_strategy TEXT CHECK (ax_strategy IN ('none','manual','enhanced')), source TEXT NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE origin_policies (pattern TEXT PRIMARY KEY, mode TEXT NOT NULL CHECK (mode IN ('allowed','confirm_all','denied')), max_actions_per_hour INTEGER, source TEXT NOT NULL, updated_at INTEGER NOT NULL) STRICT;
CREATE TABLE origin_activity (origin TEXT NOT NULL, hour INTEGER NOT NULL, actions INTEGER NOT NULL, PRIMARY KEY (origin, hour)) STRICT, WITHOUT ROWID;
CREATE TABLE packs (id TEXT PRIMARY KEY, version TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 0, embedded INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL, sha256 TEXT NOT NULL, partially_supported INTEGER NOT NULL DEFAULT 0, consent TEXT NOT NULL CHECK (json_valid(consent)), installed_at INTEGER NOT NULL, enabled_at INTEGER) STRICT;
CREATE TABLE pack_keys (pack_id TEXT NOT NULL, env_name TEXT NOT NULL, account TEXT NOT NULL, detail TEXT, checked_at INTEGER, status TEXT NOT NULL CHECK (status IN ('missing','present','invalid','unchecked','limited')), PRIMARY KEY (pack_id, env_name)) STRICT;
CREATE TABLE routine_runs (id TEXT PRIMARY KEY, task_id TEXT REFERENCES tasks ON DELETE SET NULL, pack_id TEXT NOT NULL, routine TEXT NOT NULL, match_confidence REAL, params TEXT CHECK (json_valid(params)), outcome TEXT NOT NULL CHECK (outcome IN ('passed','verify_failed','step_failed','handoff','cancelled')), dur_ms INTEGER, at INTEGER NOT NULL) STRICT;
CREATE TABLE spend_events (id TEXT PRIMARY KEY, at INTEGER NOT NULL, day TEXT NOT NULL, task_id TEXT REFERENCES tasks ON DELETE SET NULL, kind TEXT NOT NULL CHECK (kind IN ('sol','text_helper','stt','tts','jev','fal','quiver','pack')), provider TEXT NOT NULL, model TEXT, units TEXT NOT NULL CHECK (json_valid(units)), usd REAL NOT NULL, exact INTEGER NOT NULL) STRICT;
CREATE TABLE spend_daily (day TEXT NOT NULL, kind TEXT NOT NULL, usd REAL NOT NULL, calls INTEGER NOT NULL, PRIMARY KEY (day, kind)) STRICT, WITHOUT ROWID;
CREATE TABLE models (provider TEXT NOT NULL, id TEXT NOT NULL, use_case TEXT NOT NULL, capabilities TEXT NOT NULL CHECK (json_valid(capabilities)), price TEXT CHECK (json_valid(price)), price_source TEXT, hidden INTEGER NOT NULL DEFAULT 0, first_seen INTEGER NOT NULL, last_seen INTEGER NOT NULL, PRIMARY KEY (provider, id)) STRICT;
CREATE TABLE studios (id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL UNIQUE, take_count INTEGER NOT NULL DEFAULT 0, last_take TEXT, frame_count INTEGER NOT NULL DEFAULT 0, brand TEXT CHECK (json_valid(brand)), missing INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, last_opened_at INTEGER) STRICT;
